shader:
// Slices - Swiss motion-design strip push.
// The frame is cut into N parallel strips (the strip MASK is tilted by `angle`). Every strip is a
// rigid tape [B][A] that slides along screen X by exactly the frame width: every pixel row moves
// the same amount, so B's real vertical border leads, nothing is sampled outside the picture and
// there is no shear / edge creep at any angle.
// A accelerates out (strong ease-in), B rides in right behind it and lands with a crisp ease-out
// plus a small scale settle. Strips start one after another (`stagger`, top first) and alternate
// direction. Motion blur = temporal supersampling (jittered shutter taps, one texture tap each);
// strip edges are anti-aliased by jittering the strip lookup inside the pixel footprint.

const int SL_TAPS = 32;

// asymmetric power in-out, C1 at the midpoint: short wind-up, fast middle, crisp landing
float slEase(float x) {
    x = clamp(x, 0.0, 1.0);
    const float k1 = 3.0;            // ease-in power
    const float k2 = 4.0;            // ease-out power
    const float a = k2 / (k1 + k2);  // value at x = 0.5 (keeps the speed continuous)
    if (x < 0.5) return a * pow(2.0 * x, k1);
    return 1.0 - (1.0 - a) * pow(2.0 - 2.0 * x, k2);
}

vec2 slUv(vec2 P) { return vec2(P.x / ratio + 0.5, P.y + 0.5); }

vec4 transition(vec2 uv) {
    float ang = radians(clamp(angle, -30.0, 30.0));
    vec2 nd = vec2(-sin(ang), cos(ang));    // across the strips (aspect-correct space)
    vec2 P = vec2((uv.x - 0.5) * ratio, uv.y - 0.5);

    float hs = 0.5 * (ratio * abs(nd.x) + abs(nd.y));  // half extent of the frame across the strips
    float n = max(floor(count + 0.5), 1.0);
    float spread = clamp(stagger, 0.0, 0.75);
    float w = 1.0 - spread;
    float px = 1.0 / resolution.y;
    float s = dot(P, nd);
    // rigid tape: travel = frame width (+3 px so no sliver of the old frame survives)
    float L = ratio + 3.0 * px;
    float x0 = -0.5 * ratio - 1.5 * px;
    float x1 = 0.5 * ratio + 1.5 * px;
    float sh = max(blur, 0.0) * 0.042;                 // shutter in progress units (~180-270 deg at 30 fps)
    sh *= clamp(min(progress, 1.0 - progress) / max(sh, 1e-4), 0.0, 1.0); // closes at both ends: exact A / B
    const float Z = 0.07;                              // depth: A swells as it leaves, B settles from 1.07

    // interleaved gradient noise, re-seeded every frame so the faint tap pattern never sits fixed on screen
    float nz = fract(52.9829189 * fract(dot(gl_FragCoord.xy + 5.588238 * floor(time * 30.0), vec2(0.06711056, 0.00583715))));
    float nz2 = fract(nz * 13.37 + 0.5);

    vec3 acc = vec3(0.0);
    for (int j = 0; j < SL_TAPS; j++) {
        float fj = float(j);
        float u = (fj + nz) / float(SL_TAPS);
        float v = fract(fj * 0.6180339 + nz2);
        float pj = clamp(progress + (u - 0.5) * sh, 0.0, 1.0);
        float sj = s + (v - 0.5) * px * 1.4;
        float idx = clamp(floor((sj / (2.0 * hs) + 0.5) * n), 0.0, n - 1.0);
        float rank = n - 1.0 - idx;                                  // top strip leaves first
        float st = n > 1.5 ? spread * rank / (n - 1.0) : 0.0;
        float o = slEase((pj - st) / w);
        float dir = mod(idx, 2.0) < 0.5 ? 1.0 : -1.0;
        float edge = dir > 0.0 ? x0 + o * L : x1 - o * L;            // A|B joint (vertical)
        vec3 c;
        if ((P.x - edge) * dir > 0.0) {
            c = getA(slUv(vec2(P.x - dir * o * L, P.y) / (1.0 + Z * o))).rgb;
        } else {
            c = getB(slUv(vec2(P.x + dir * (1.0 - o) * L, P.y) / (1.0 + Z * (1.0 - o)))).rgb;
        }
        acc += c;
    }
    return vec4(acc / float(SL_TAPS), 1.0);
}
